text:
{
  "axioms": [
    "灯台の灯りは嵐の夜に消してはいけない。消えれば入り江を目指す船は岩に乗り上げる。",
    "死者は戻らない。死んだ人物について語れるのは、本人が遺した物と言葉だけである。"
  ],
  "rules": [
    {
      "id": "rule-1",
      "statement": "嵐の夜、灯台守は日没から夜明けまで灯りを絶やしてはいけない",
      "cost": "守る者は夜通し灯室を離れられず、眠れない",
      "constraint": "油の補給と芯の手入れが繰り返し要り、一人では何夜も続かない",
      "exception": "海が凪いだ霧の夜だけ、仮灯で短く休める",
      "exception_condition": "嵐ではなく港町側から仮灯の合図がある場合に限る"
    },
    {
      "id": "rule-2",
      "statement": "灯台の鍵は灯台守の家の者だけが持ち、貸すときは相手と理由を明らかにする",
      "cost": "鍵が戻るまで灯室の扉を閉めて守れない",
      "constraint": "鍵は限られており、貸した鍵が戻らなければ灯りの管理自体が危うくなる",
      "exception": "人命の危険がある緊急時だけ、記録より先に貸せる",
      "exception_condition": "入り江に船が避難している場合に限る"
    },
    {
      "id": "rule-3",
      "statement": "灯台と港町の往来には山道でも船でも二日かかる",
      "cost": "往復で四日かかり、留守の灯りは残る者に託すしかない",
      "constraint": "嵐の日は船が出ず、山道も荒れて渡れない",
      "exception": "",
      "exception_condition": ""
    }
  ],
  "institutions": [
    {"name": "灯台守の家", "role": "灯台の点灯と鍵の管理を引き継ぐ"},
    {"name": "港町の船問屋", "role": "出入りする船の取り次ぎと仮灯の合図を担う"}
  ],
  "geography": ["灯台", "港町"],
  "disclosure": [
    {"info": "灯りを消してはいけないという掟", "chapter": "ch01"},
    {"info": "鍵に姉の貝の印があり、トキに託されていたこと", "chapter": "ch02"},
    {"info": "平作が三年前の夜について黙っていた理由", "chapter": "ch03"}
  ],
  "notes": ""
}
